def is_multiply_prime(a: int) -> bool:
    if a < 2:
        return False
    n = a
    factors = []
    p = 2
    while p * p <= n:
        while n % p == 0:
            factors.append(p)
            n //= p
        p += 1
    if n > 1:
        factors.append(n)
    return len(factors) == 3
